CONTRACT (from /workspace/INSTRUCTION.md)
Deliverable: /app/setup.sh, run as root via `bash /app/setup.sh` in fresh Debian container.
Check: real HTTP requests to localhost:8080 after script exits.
Reqs: install nginx; listen 8080; root /var/www/html;
access log /var/log/nginx/benchmark-access.log with $time_local,$request_method,$status,quoted $http_user_agent;
error log /var/log/nginx/benchmark-error.log;
limit_req_zone in /etc/nginx/nginx.conf (10 req/s per IP, zone 10m); limit_req burst=10 in server block;
error_page 404 -> /404.html; server conf at /etc/nginx/conf.d/benchmark-site.conf;
rm /etc/nginx/sites-enabled/default; mkdir -p /var/www/html;
index.html="Welcome to the benchmark webserver"; 404.html="Page not found - Please check your URL";
log_format in nginx.conf if absent; nginx -t before start; nginx up on :8080 when script exits.
Self-contained. Idempotency welcome.
SANDBOX: not root, no sudo; nginx 1.26.3 installed here -> test with path-rewritten copy under /tmp.
EOF
cat > /app/setup.sh <<'SCRIPT'
#!/usr/bin/env bash
# Placeholder stub - full version lands here next.
exit 0
SCRIPT
chmod +x /app/setup.sh
ls -l /app/setup.sh && bash -n /app/setup.sh && echo stub_ok"}

{"command": "cat > /tmp/harness.sh <<'HARNESS'
#!/usr/bin/env bash
set -euo pipefail
FAKE=/tmp/fake
rm -rf "$FAKE"
mkdir -p "$FAKE"/{etc,run}
# Fresh-container nginx config tree: copy real one + add the default site (present on fresh Debian)
cp -a /etc/nginx "$FAKE/etc/nginx"
mkdir -p "$FAKE/etc/nginx/sites-enabled"
cat > "$FAKE/etc/nginx/sites-enabled/default" <<'DEF'
server {
    listen 80 default_server;
    server_name _;
    root /var/www/html;
    location / {
        try_files $uri $uri/ =404;
    }
}
DEF
mkdir -p "$FAKE/var/www/html" "$FAKE/var/log/nginx"
# Path-rewritten copy of the deliverable (simulates running as root in the fresh container)
sed -e 's|/etc/|/tmp/fake/etc/|g' \
    -e 's|/var/log/nginx|/tmp/fake/var/log/nginx|g' \
    -e 's|/var/www|/tmp/fake/var/www|g' \
    -e 's|/run/|/tmp/fake/run/|g' \
    /app/setup.sh > /tmp/fake_setup.sh
# Fake `service` that fails so the script's direct-start fallback is exercised
mkdir -p /tmp/fakebin
printf '#!/bin/bash\nexit 1\n' > /tmp/fakebin/service
chmod +x /tmp/fakebin/service
export PATH="/tmp/fakebin:$PATH"
bash /tmp/fake_setup.sh
HARNESS
chmod +x /tmp/harness.sh
/tmp/harness.sh > /tmp/run1.log 2>&1; echo "rc=$?"; tail -25 /tmp/run1.log", "timeout": 300}

